// Get the structured output from OpenAI
const aiOutput = $node["OpenAI - Parse Invoice"].json.message.content;

// Get the email data from the Trigger (using the correct method for v2)
const emailData = $('Gmail Trigger').first().json;

try {
  // Since OpenAI returned a JSON object directly, we don't need to parse it
  const formattedData = {
    date: aiOutput.date || 'UNKNOWN',
    amount: aiOutput.amount || 0,
    currency: aiOutput.currency || 'USD',
    vendor: aiOutput.vendor || 'UNKNOWN',
    description: aiOutput.description || '',
    invoice_number: aiOutput.invoice_number || '',
    confidence: aiOutput.confidence || 'low',
    email_subject: emailData.Subject || 'No Subject', // Gmail Trigger uses capital 'S'
    email_from: emailData.From || 'Unknown Sender',  // Gmail Trigger uses capital 'F'
    processed_at: new Date().toISOString(),
    status: 'auto-processed'
  };

  return [{ json: formattedData }];

} catch (error) {
  return [{
    json: {
      status: 'needs-review',
      error_message: error.message,
      processed_at: new Date().toISOString()
    }
  }];
}
